mapper.update:

UPDATE ICOMIVDT				
SET 
	  INVOICE_DATE = #{st_invoice_date}
	, CHANGE_DATE  = TO_CHAR(SYSDATE,'YYYYMMDD')
	, CHANGE_TIME  = TO_CHAR(SYSDATE,'HH24MISS')
WHERE
		INV_NO	= #{st_inv_no}
	AND BUYER	= #{st_buyer}


UPDATE ICOMIVHD                                 
SET  
	  INV_DATE       = #{st_invoice_date}                       
	, CHANGE_DATE    = TO_CHAR(SYSDATE,'YYYYMMDD')
	, CHANGE_TIME    = TO_CHAR(SYSDATE,'HH24MISS')
	, CHANGE_USER_ID = #{st_user_id}
	, PARCEL_YN		 = #{st_parcel_yn}    
WHERE  
		INV_NO	= #{st_inv_no} 
	AND BUYER	= #{st_buyer}


UPDATE ICOMIVDT
SET 
	  STATUS		= 'D'
	, SND_CHK		= 'N'
	, CHANGE_DATE	= TO_CHAR(SYSDATE,'YYYYMMDD')
	, CHANGE_TIME	= TO_CHAR(SYSDATE,'HH24MISS')      
WHERE
		INV_NO      = #{inv_no}
	AND SELLER      = #{seller}
	AND BUYER       = #{buyer}


UPDATE ICOMPORS
SET COMPLETE_MARK = 'N'
WHERE
		BUYER		= #{buyer}
	AND PO_NO		= #{po_no}
	AND PO_SEQ		= #{po_seq}
	AND DS_DATE		= #{ds_date}
	AND STATUS	   != 'D'


UPDATE  ICOMPODT
SET
	  IV_QTY = DECODE(PROCESS_TYPE,'2',NVL(IV_QTY,0),(
						SELECT NVL(SUM(INV_QTY),0)
						FROM ICOMIVDT
						WHERE
								BUYER   = #{buyer}
							AND SELLER  = #{seller}
							AND PO_NO   = #{po_no}
							AND PO_SEQ  = #{po_seq}
							AND STATUS != 'D'))
	, DI_QTY = DECODE(PROCESS_TYPE,'2',NVL(DI_QTY,0),(
						SELECT NVL(SUM(DELIVERY_QTY),0)
						FROM ICOMIVDT
						WHERE
								BUYER   = #{buyer}
							AND SELLER  = #{seller}
							AND PO_NO   = #{po_no}
							AND PO_SEQ  = #{po_seq}
							AND STATUS != 'D'))
	, COMPLETE_MARK = 'N'
WHERE
		BUYER         = #{buyer}
	AND SELLER        = #{seller}
	AND PO_NO         = #{po_no}
	AND PO_SEQ        = #{po_seq}
	AND STATUS       != 'D'


UPDATE ICOMPOHD                                        
SET COMPLETE_MARK = 'N'                             
WHERE
		BUYER  = #{buyer}   
	AND SELLER = #{seller}  
	AND PO_NO  = #{po_no}
